 const notes=game.notes('riddle-text',source,null,text),active=game.riddleState().active;for(const language of (active?.sage===currentSage?active.translations:sageResult?.translations)||[])if(text[language]&&!notes.some(note=>note.language===language&&note.kind==='phrase'))notes.push({text:text[language],language,via:'Translation scroll'});
 for(const note of notes){const hint=el('span',`${note.text} [${t(WORLD.languages[note.language])} · ${t(note.via)}]`,'note',note.language);hint.lang=note.language;container.append(hint);}return container;
