 if(active&&active.sage===id){const riddle=WORLD.riddles[active.riddle];sageModal.append(el('p',`${local('Stake paid','Vklad zaplacen')}: ${coins(active.stake)}`),sageLine(riddle.question,'riddle-question','h3'));const answers=el('div',undefined,'riddle-answers');riddle.answers.forEach((answer,index)=>{const b=button('',()=>{sageResult={id:active.riddle,...game.answerRiddle(id,index)};renderSage();});b.dataset.answer=index;b.lang=sage.language;b.append(sageLine(answer,'riddle-answer'));answers.append(b);});sageModal.append(answers,el('p',local('Closing this conversation leaves the wager pending.','Zavřením rozhovoru zůstane sázka nerozhodnutá.'),'muted'));const tools=el('div',undefined,'riddle-translation-tools');for(const [scrollId,count]of Object.entries(game.state.inventory)){const scroll=WORLD.items[scrollId],target=scroll.target==='native'?game.state.native:scroll.target;if(count>0&&scroll.type==='scroll'&&target!==sage.language&&!active.translations?.includes(target))tools.append(button(`${local('Translate this riddle','Přeložit tuto hádanku')} · ${t(scroll.name)}`,()=>{game.castRiddle(id,scrollId);renderSage();}));}sageModal.append(tools);return;}
 if(active){const owner=WORLD.npcs[active.sage].name.split(' · ')[0];sageModal.append(el('p',local(`Finish your pending wager with ${owner} first.`,`Nejprve dokonči rozjednanou sázku s mudrcem ${owner}.`)));return;}
