function closeIcon(label,fn){const b=el('button','\u00d7','modal-close');b.type='button';b.setAttribute('aria-label',t(label));b.title=t(label);b.onclick=fn;return b;}
function speechControl(){const control=el('button',undefined,'speech-toggle');control.innerHTML='<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true" focusable="false"><path d="M3 9h4l5-4v14l-5-4H3z" fill="currentColor"/><path class="speech-waves" d="M16 8q4 4 0 8M19 5q7 7 0 14" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/><path class="speech-muted" d="m16 9 6 6m0-6-6 6" fill="none" stroke="currentColor" stroke-width="1.6"/></svg>';control.setAttribute('aria-label',bookLabel('Speech','Předčítání'));control.type='button';control.setAttribute('aria-pressed',String(speech.enabled));control.disabled=!speech.provider.available?.()&&speech.provider instanceof BrowserSpeechProvider;control.title=bookLabel('Toggle reading aloud. Click a passage or choose a dialogue reply. A matching installed voice is required.','Zapnout či vypnout předčítání. Klikni na text nebo zvol odpověď. Je nutný nainstalovaný hlas daného jazyka.');control.onclick=()=>{speech.setEnabled(!speech.enabled);updateSpeechUI();};return control;}
function speechTarget(node){return node.closest?.('.response-text,.book-page p,.book-page h3,#conversation .line p[lang],.transcript-body p[lang],.note[lang]');}
function speechLanguage(node){return node.closest('[lang]')?.lang;}
function alignModalHeaders(){for(const modal of document.querySelectorAll('dialog')){const bar=modal.querySelector(':scope > .modal-close-bar');if(!bar)continue;const heading=modal.querySelector(':scope > .dialogue-modal-header,:scope > h2');if(heading){heading.classList.add('modal-heading');bar.prepend(heading);}}}
function updateSpeechUI(){alignModalHeaders();for(const control of document.querySelectorAll('.speech-toggle')){const label=bookLabel('Speech','Předčítání');control.setAttribute('aria-label',label);control.setAttribute('aria-pressed',String(speech.enabled));}for(const node of document.querySelectorAll('.response-text,.book-page p,.book-page h3,#conversation .line p[lang],.transcript-body p[lang],.note[lang]')){const supported=speech.supports(speechLanguage(node));node.classList.toggle('speech-readable',speech.enabled&&supported);node.classList.toggle('speech-unavailable',speech.enabled&&!supported);if(!node.closest('button')){node.tabIndex=speech.enabled&&supported?0:-1;}node.title=speech.enabled?bookLabel(supported?'Click to read aloud':'Speech unavailable for this language on this device',supported?'Klikni pro předčítání':'Předčítání tohoto jazyka na tomto zařízení není dostupné'):'';}}
document.addEventListener('click',event=>{const node=speechTarget(event.target)||event.target.closest?.('#choices button')?.querySelector('.response-text');if(node&&!node.closest('button:disabled')){if(speech.enabled&&node.matches('.note')&&node.closest('button'))event.stopPropagation();speech.speak(node.dataset.speechText||node.textContent,speechLanguage(node));}},{capture:true});
