function requestTravel(id,onArrival){closeSidebarDialogs();if(!game.canTravel(id))throw Error('Follow the quest trail before travelling here.');if(id===game.state.location){if(onArrival)onArrival();return;}if(dialogueModal.open)closeDialogueModal();if(reader.open)reader.close();if(parchment.open)parchment.close();if(archiveModal.open)archiveModal.close();const from=WORLD.locations.find(place=>place.id===game.state.location),to=WORLD.locations.find(place=>place.id===id),title=el('h2',`${t(from.name)} \u2192 ${t(to.name)}`);title.id='travel-modal-title';travelModal.setAttribute('aria-labelledby',title.id);const rows=[closeBar(closeIcon('Close travel window',()=>travelModal.close())),el('span',t('Arrange transport'),'eyebrow'),title,el('p',t('Choose transport to begin your journey.'),'muted'),el('p',`${t('Your purse')}: ${coins(game.state.gold)}`)];const quotes=game.transportOptions(id);if(!quotes.length)rows.push(el('p',t('Sea crossings require boat passage between port cities. Travel to a port first.'),'muted'));for(const quote of quotes){const option=button('',()=>{const firstVisit=!game.state.visitedLocations.includes(id);game.travel(id,quote.id);showJourney(to,quote,onArrival,firstVisit);},game.state.gold<quote.cost);option.className='transport-option';const icon=el('img',undefined,'transport-icon');icon.src=`assets/transport/${quote.id}-painted.png`;icon.alt='';icon.width=64;icon.height=64;icon.setAttribute('aria-hidden','true');const copy=el('span',undefined,'transport-copy');copy.append(el('strong',t(quote.label)),el('span',`${coins(quote.cost)} \u00b7 ${journeyDuration(quote.days)}`));if(option.disabled)copy.append(el('small',t('Not enough coins for this journey.'),'muted'));option.append(icon,copy);rows.push(option);}rows.push(el('p',t('Shared currency: 1 gold = 100 silver = 10,000 copper.'),'muted'));travelModal.replaceChildren(...rows);if(!travelModal.open)travelModal.showModal();}
let finishJourney=null;
