function reputationBadge(value,scope){
 const status=value<=-25?'hostile':value<0?'distrusted':value>=20?'respected':value>0?'friendly':'neutral';
 const labels={hostile:reputationText('Hostile','Nepřátelský'),distrusted:reputationText('Distrusted','Nedůvěra'),neutral:reputationText('Neutral','Neutrální'),friendly:reputationText('Friendly','Přátelský'),respected:reputationText('Respected','Vážený')};
 const label=reputationText({person:'Person',city:'City',country:'Country'}[scope],{person:'Osoba',city:'Město',country:'Země'}[scope]);
 const badge=el('span',undefined,'reputation-badge '+status);badge.dataset.scope=scope;badge.dataset.standing=status;badge.title=`${label}: ${labels[status]} (${value})`;
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 28 28');svg.setAttribute('aria-hidden','true');svg.classList.add('reputation-icon');
 const part=(tag,attrs)=>{const node=document.createElementNS(svg.namespaceURI,tag);for(const [key,v]of Object.entries(attrs))node.setAttribute(key,v);svg.append(node);};
 part('circle',{cx:14,cy:14,r:11,fill:'currentColor','fill-opacity':'.12',stroke:'currentColor','stroke-width':1.5});
 if(scope==='person'){part('circle',{cx:10,cy:11,r:1,fill:'currentColor'});part('circle',{cx:18,cy:11,r:1,fill:'currentColor'});part('path',{d:value<0?'M9 19 Q14 13 19 19':value>0?'M9 16 Q14 22 19 16':'M9 18 H19',fill:'none',stroke:'currentColor','stroke-width':1.7,'stroke-linecap':'round'});if(status==='hostile')part('path',{d:'M8 7 L12 9 M16 9 L20 7',stroke:'currentColor','stroke-width':1.5});}
 else{part('path',{d:'M7 20V10H10V13H12V8H16V13H18V10H21V20Z M12 20V16H16V20',fill:'none',stroke:'currentColor','stroke-width':1.4});part('path',{d:value<0?'M19 4 L25 10 M25 4 L19 10':value>0?'M19 7 L22 10 L26 4':'M20 7 H26',fill:'none',stroke:'currentColor','stroke-width':2,'stroke-linecap':'round'});}
 if(status==='respected')part('path',{d:'M14 1L15 3L18 3L16 5L17 8L14 6L11 8L12 5L10 3L13 3Z',fill:'currentColor'});
 badge.append(svg,el('span',`${label}: ${labels[status]} (${value})`));return badge;
}
