function showQuestCompletions(before){
 if(before.state!==game.state){closeSidebarDialogs();questNotifications.replaceChildren();if(questNotifications.matches(':popover-open'))questNotifications.hidePopover();return;}
 const added=game.state.milestones.filter(id=>!before.milestones.includes(id)),titles=[];
 const quests=Object.values(WORLD.quests),starts=quests.filter(quest=>quest.kind==='investigation').map(quest=>quest.started);
 for(const id of added){const quest=quests.find(quest=>quest.completion===id);const place=WORLD.locations.find(place=>(place.milestone||place.id)===id);
  if(quest)titles.push(t(quest.title));
  else if(id===WORLD.quest.finalMilestone)titles.push(t(WORLD.quest.title));
  else if(id===WORLD.quest.resolutionMilestone)titles.push(t('The three Irish sanctuaries'));
  else if(place&&!starts.includes(id))titles.push(`${t(place.name)} · ${t(WORLD.quest.title)}`);
 }
 for(const id of game.state.repairedSetbacks)if(!before.repairs.includes(id))titles.push(t(WORLD.quests[id].title));
 const unlocked=WORLD.locations.filter(place=>!before.unlocked.includes(place.id)&&game.canTravel(place.id));
 if(!titles.length&&!unlocked.length)return;
 sounds.play('quest');
 const rewards=[],money=game.state.history.slice(before.history).filter(event=>event.label==='Reward received').reduce((sum,event)=>sum+(event.gold||0),0);
 if(money>0)rewards.push({id:'coins',text:coins(money)});
 for(const [id,count]of Object.entries(game.state.inventory)){const gained=count-(before.inventory[id]||0);if(gained>0)rewards.push({id,text:`${t(WORLD.items[id].name)}${gained>1?' ×'+gained:''}`});}
 const toast=el('section',undefined,'quest-toast');toast.append(el('strong',titles.length?`${t('Quest completed!')} ${[...new Set(titles)].join(' · ')}`:t('New destinations unlocked!')));
 if(rewards.length){const rewardLine=el('div',undefined,'quest-rewards');rewardLine.append(el('span',`${t('Reward')}: `));for(const reward of rewards){const entry=el('span',undefined,'item-reward');entry.append(itemIcon(reward.id),WORLD.items[reward.id]?.title?bookTitle(reward.id):el('span',reward.text));rewardLine.append(entry);}toast.append(rewardLine);}
 if(unlocked.length)toast.append(el('p',`${t('New destinations available')}: ${unlocked.map(place=>t(place.name)).join(', ')}`,'quest-unlocks'));
 let timer;const dismiss=()=>{clearTimeout(timer);toast.remove();if(!questNotifications.children.length&&questNotifications.matches(':popover-open'))questNotifications.hidePopover();};
 const close=button('×',dismiss);close.className='quest-toast-close';close.setAttribute('aria-label',t('Dismiss notification'));toast.append(close);
 const schedule=()=>{clearTimeout(timer);timer=setTimeout(dismiss,8000);};toast.onmouseenter=()=>clearTimeout(timer);toast.onmouseleave=schedule;toast.onfocusin=()=>clearTimeout(timer);toast.onfocusout=schedule;
 const host=[...document.querySelectorAll('dialog[open]')].at(-1)||document.body;
 if(questNotifications.parentElement!==host){if(questNotifications.matches(':popover-open'))questNotifications.hidePopover();host.append(questNotifications);}
 questNotifications.append(toast);while(questNotifications.children.length>3)questNotifications.firstElementChild.remove();
 if(!questNotifications.matches(':popover-open'))questNotifications.showPopover();schedule();
}
function action(fn,message){try{const before=questSnapshot(),previousLocation=game.state.location,wasComplete=game.state.milestones.includes(WORLD.quest.finalMilestone),wasResolved=game.state.milestones.includes(WORLD.quest.resolutionMilestone);const result=fn();render();if(!wasComplete&&game.state.milestones.includes(WORLD.quest.finalMilestone)||!wasResolved&&game.state.milestones.includes(WORLD.quest.resolutionMilestone))showConclusion();showQuestCompletions(before);$('notice').textContent=message||(typeof result==='string'?result:'');if(game.state.location!==previousLocation)scrollToScene();}catch(e){$('notice').textContent=t(e.message);}}
