function renderHistory(){const navigation=el('div',undefined,'journal-tabs');for(const view of ['events','dialogues']){const b=button(t({rumors:'Heard rumors',events:'Events',dialogues:'Conversations'}[view]),()=>{journalView=view;});b.setAttribute('aria-pressed',String(journalView===view));navigation.append(b);}const rows=[navigation];if(journalView==='events'){for(const event of [...game.state.history].reverse()){const row=el('div',undefined,'journal-event');if(event.date){const date=new Date(event.date);if(!Number.isNaN(date.getTime())){const stamp=el('time',calendarDate(event.date),'event-date');stamp.dateTime=event.date;row.append(stamp);}}if(event.transport)row.append(el('p',`${t(event.transport)} \u00b7 ${coins(event.cost)}`,'muted'));if(event.days)row.append(el('span',journeyDuration(event.days),'muted'));const place=WORLD.locations.find(l=>l.id===event.location);row.append(el('span',t(place.name),'eyebrow'),el('p',t(event.label)));if(event.from)row.append(el('p',`${t(WORLD.locations.find(l=>l.id===event.from).name)} \u2192 ${t(place.name)}`,'muted'));if(event.item)row.append(el('p',`${t(WORLD.items[event.item].name)}${event.count?' \u00d7'+event.count:''}`,'muted'));if(event.setback)row.append(el('p',t(WORLD.quests[event.setback].title),'muted'));if(event.companion)row.append(personReference('p',WORLD.companions[event.companion].name,event.companion,'muted'));if(event.gold)row.append(el('p',coins(event.gold),'muted'));for(const item of event.items||[])row.append(el('p',`${t(WORLD.items[item.item].name)} \u00d7${item.count}`,'muted'));if(event.milestone){const quest=Object.values(WORLD.quests).find(q=>q.completion===event.milestone||q.started===event.milestone);const step=Object.values(WORLD.quests).flatMap(q=>q.steps||[]).find(step=>step.milestone===event.milestone);const location=WORLD.locations.find(l=>(l.milestone||l.id)===event.milestone);row.append(el('p',t(quest?.title||step?.label||location?.name||'Progress recorded'),'muted'));}rows.push(row);}}else{for(const session of [...game.state.conversations].reverse()){const details=el('details',undefined,'journal-conversation');details.append(personReference('summary',`${t(WORLD.npcs[session.npcId].name)} \u00b7 ${t(WORLD.locations.find(l=>l.id===session.location).name)} \u00b7 ${session.entries.length}`,session.npcId),button(t('Open conversation'),()=>showArchive(session)),...transcriptRows(session));rows.push(details);}}$('journal').replaceChildren(...rows);}
function requirementsText(requirements){return game.missingRequirements(requirements).map(entry=>{if(entry.type==='setback')return `${t('Resolve before continuing')}: ${t(WORLD.quests[entry.id].title)}`;if(entry.type==='recovery')return t('There is no active harm to repair.');if(entry.type==='completed')return t('This lead is already settled.');if(entry.type==='item')return t(WORLD.items[entry.id].name)+(entry.count?` ×${entry.count}`:'');const investigation=Object.values(WORLD.quests).find(q=>q.kind==='investigation'&&q.completion===entry.id);if(investigation)return t(investigation.title);const lead=Object.values(WORLD.quests).filter(q=>q.kind==='investigation').flatMap(q=>q.steps).find(step=>step.milestone===entry.id);if(lead)return t(lead.label);if(entry.id==='latin_deciphered')return t('Decipher both Latin pages');const location=WORLD.locations.find(l=>(l.milestone||l.id)===entry.id);return location?`${t('Complete')}: ${t(location.name)}`:t('Accept the errand');}).join(', ');}
