 if(!voyageMap)voyageMap=new VoyageMapTools.VoyageMap($('world-map'),mapData,WORLD,game,id=>action(()=>requestTravel(id)),t,requirementsText,regionalData);else voyageMap.render();
 game.rememberTranslations();
 dialogueLog.replaceChildren(el('summary',t('Dialogue log')), ...transcriptRows(game.conversation));
 const s=game.state,place=WORLD.locations.find(l=>l.id===s.location);renderCharacter();
 const countryGroups=new Map();for(const location of WORLD.locations){if(!game.canTravel(location.id))continue;if(!countryGroups.has(location.country))countryGroups.set(location.country,[]);countryGroups.get(location.country).push(location);}
